#!/bin/sh
# Regenerates the PGO profile of the release CLI (scripts/build_release.sh, docs/build-optimization.md):
#   <main checkout>/.reference/pgo/elk-lean-<lean version>-<os>-<arch>.profdata   (+ .txt provenance)
# The profile is toolchain-specific binary data, so it lives with the other reproducible reference
# data under .reference/ (not in git) and is regenerated by this script after Lean or toolchain
# changes (a stale profile still builds; changed functions are just compiled without profile).
#
# Steps:
# 1. the LLVM profile runtime (compiler-rt/lib/profile) at the exact LLVM commit of the toolchain
#    clang (`clang --version`; the Lean toolchain ships no libclang_rt.profile, and the raw profile
#    format must match the instrumentation: Xcode's LLVM 21 runtime rejects clang 23's version 11),
#    sparse-fetched into .lake/pgo-deps/llvm-project and built with the toolchain clang;
# 2. `scripts/build_release.sh --pgo-generate`: the instrumented release CLI (ThinLTO, Elk C and runtime
#    instrumented) in .lake/build/release-pgogen;
# 3. training (deterministic: fixed inputs, counters summed per binary signature `%m`):
#    `elk bench` over the 26 synthetic scenarios (3 iterations + 1 warmup), `elk batch` over the
#    ELK Java corpus manifest (.reference/java-baseline/corpus, 1,998 inputs; else the elk-models
#    corpus via make_json_manifest.py), and `elk layout --pretty --sort-keys` over the first 200
#    graphs of the random sets s1, v1, w1 (scripts/gen_nodesize_graphs.py, sanitize_for_java.py,
#    gen_wrapping_graphs.py; one process per graph like the random parity runs);
# 4. `llvm-profdata merge` -> the profile above.
# Then `sh scripts/build_release.sh` picks the profile up.
#
# usage: sh scripts/build_pgo.sh [--keep-raw]
# env: LLVM_PROFDATA  llvm-profdata that reads the raw format of the toolchain clang (default: the
#                     one of the pinned emsdk under .reference/emsdk, LLVM 24git, which reads raw
#                     version 11 and writes an index clang 23 accepts; Xcode's does not)
#      ELK_PGO_PROFILE, JOBS (as scripts/build_release.sh)
set -eu
HERE=$(cd "$(dirname "$0")/.." && pwd)
cd "$HERE"
export PATH="$HOME/.elan/bin:$PATH"
REF="$HERE/.reference"
if [ ! -d "$REF" ]; then
  COMMON=$(git -C "$HERE" rev-parse --path-format=absolute --git-common-dir 2>/dev/null || true)
  if [ -n "$COMMON" ]; then REF="$(dirname "$COMMON")/.reference"; fi
fi
KEEP_RAW=0
[ "${1:-}" = "--keep-raw" ] && KEEP_RAW=1
LEAN_V=$(lean --short-version)
LEAN_PREFIX=$(lean --print-prefix)
CC="$LEAN_PREFIX/bin/clang"
ARCH=$(uname -m)
OS=$(uname -s | tr 'A-Z' 'a-z')
PROFILE=${ELK_PGO_PROFILE:-"$REF/pgo/elk-lean-$LEAN_V-$OS-$ARCH.profdata"}
PD=${LLVM_PROFDATA:-"$REF/emsdk/upstream/bin/llvm-profdata"}
[ -x "$PD" ] || { echo "error: llvm-profdata not found at $PD (set LLVM_PROFDATA)" >&2; exit 1; }
W="$HERE/.lake/build/pgo"
mkdir -p "$W"

# --- 1. profile runtime of the toolchain's LLVM commit ------------------------------------------
LLVM_COMMIT=$("$CC" --version | sed -n 's/.*llvm-project \([0-9a-f]\{40\}\)).*/\1/p' | head -1)
[ -n "$LLVM_COMMIT" ] || { echo "error: cannot read the LLVM commit of $CC" >&2; exit 1; }
SRC="$HERE/.lake/pgo-deps/llvm-project"
if [ "$(git -C "$SRC" rev-parse HEAD 2>/dev/null || true)" != "$LLVM_COMMIT" ]; then
  rm -rf "$SRC"; mkdir -p "$SRC"
  git -C "$SRC" init -q
  git -C "$SRC" remote add origin https://github.com/llvm/llvm-project
  git -C "$SRC" sparse-checkout set --no-cone /compiler-rt/lib/profile/ /compiler-rt/include/profile/
  git -C "$SRC" fetch -q --depth 1 --filter=blob:none origin "$LLVM_COMMIT"
  git -C "$SRC" checkout -q FETCH_HEAD
fi
CRT="$SRC/compiler-rt"
PRT="$W/libclang_rt.profile.a"
case "$(uname -s)" in
  Darwin) SYS="-isysroot $(xcrun --show-sdk-path)"; PLAT=InstrProfilingPlatformDarwin ;;
  *) SYS=""; PLAT=InstrProfilingPlatformLinux ;;
esac
mkdir -p "$W/rt"
# lib/profile/CMakeLists.txt: PROFILE_SOURCES for a hosted POSIX target, with its feature defines
for f in InstrProfiling InstrProfilingBuffer InstrProfilingFile InstrProfilingInternal InstrProfilingMerge \
         InstrProfilingMergeFile InstrProfilingNameVar $PLAT InstrProfilingPlatformOther \
         InstrProfilingUtil InstrProfilingValue InstrProfilingVersionVar InstrProfilingWriter; do
  # shellcheck disable=SC2086
  "$CC" -c -O2 -fPIC $SYS -I "$CRT/include" -I "$CRT/lib/profile" -DCOMPILER_RT_HAS_ATOMICS=1 \
    -DCOMPILER_RT_HAS_FCNTL_LCK=1 -DCOMPILER_RT_HAS_UNAME=1 -fvisibility=hidden -w \
    "$CRT/lib/profile/$f.c" -o "$W/rt/$f.o"
done
# shellcheck disable=SC2086
"$CC" -c -O2 -fPIC $SYS -I "$CRT/include" -I "$CRT/lib/profile" -fno-exceptions -fno-rtti -nostdinc++ -w \
  "$CRT/lib/profile/InstrProfilingRuntime.cpp" -o "$W/rt/InstrProfilingRuntime.o"
rm -f "$PRT"
"$LEAN_PREFIX/bin/llvm-ar" rcs "$PRT" "$W"/rt/*.o
echo "profile runtime: $PRT (LLVM $LLVM_COMMIT)"

# --- 2. instrumented build ----------------------------------------------------------------------
sh scripts/build_release.sh --pgo-generate "$PRT"
BIN="$HERE/.lake/build/release-pgogen/bin/elk"

# --- 3. training ---------------------------------------------------------------------------------
RAW="$W/raw"
T="$W/train"
rm -rf "$RAW" "$T"
mkdir -p "$RAW" "$T"
export LLVM_PROFILE_FILE="$RAW/elk-%4m.profraw"
T0=$(date +%s)
"$BIN" bench --iterations 3 --warmup 1 --output "$T/bench.csv" > "$T/bench.log" 2>&1
JM="$REF/java-baseline/corpus/java_manifest.tsv"
if [ ! -f "$JM" ]; then
  JM="$T/models.tsv"
  python3 scripts/make_json_manifest.py external/elk-models "$JM" > /dev/null
fi
"$BIN" batch --input-manifest "$JM" --output-manifest "$T/batch.tsv" --layout-dir "$T/layouts" > "$T/batch.log" 2>&1 || true
python3 -I scripts/gen_nodesize_graphs.py "$T/s1" 200 1 > /dev/null
python3 -I scripts/sanitize_for_java.py "$T/s1" "$T/v1" > /dev/null
python3 -I scripts/gen_wrapping_graphs.py "$T/w1" 200 1 > /dev/null
for s in s1 v1 w1; do
  for f in "$T/$s"/*.json; do
    "$BIN" layout "$f" --pretty --sort-keys > /dev/null 2>&1 || true
  done
done
T1=$(date +%s)
echo "training: $((T1 - T0)) s, $(ls "$RAW" | wc -l | tr -d ' ') raw profiles"

# --- 4. merge ------------------------------------------------------------------------------------
mkdir -p "$(dirname "$PROFILE")"
"$PD" merge -o "$PROFILE.tmp" "$RAW"/*.profraw
mv "$PROFILE.tmp" "$PROFILE"
cat > "${PROFILE%.profdata}.txt" <<EOF
generated by scripts/build_pgo.sh on $(date '+%Y-%m-%d %H:%M:%S %z')
elk-lean: $(git -C "$HERE" rev-parse HEAD 2>/dev/null || echo unknown)
lean: $(lean --version)
compiler: $("$CC" --version | head -1)
llvm-profdata: $PD ($("$PD" --version 2>&1 | grep -i 'version' | head -1 | sed 's/^ *//'))
training: elk bench (26 scenarios, 3+1 iterations), elk batch $JM, random s1/v1/w1 x 200
sha256: $(shasum -a 256 "$PROFILE" | cut -d' ' -f1)
EOF
[ "$KEEP_RAW" = 1 ] || rm -rf "$RAW" "$T"
echo "profile: $PROFILE ($(wc -c < "$PROFILE" | tr -d ' ') bytes)"
